using System.Collections.Generic;

namespace RecursiveAI.OneHtml.Accessibility.Aria;

/// <summary>How well an entry of the <see cref="ChromiumProfile"/> is backed.</summary>
public enum ProfileEvidence
{
    /// <summary>A web-platform-tests page whose expectation the implementation passes. The pages test browsers, so this is evidence of the behaviour Chromium ships.</summary>
    TestSuite,

    /// <summary>A normative statement in the specification, with the choice among the permitted behaviours recorded.</summary>
    Specification,

    /// <summary>Seen in the output of Chrome's <c>Accessibility.getFullAXTree</c> on the fixture pages by the Chrome differential; the entry says on what.</summary>
    ChromeObserved,

    /// <summary>Inferred from public documentation or spec notes; to be confirmed by the Chrome differential.</summary>
    Unverified,
}

/// <summary>One place where the specifications leave a choice and this library made one.</summary>
/// <param name="Id">A stable identifier, used in <c>docs/accessibility-chromium-profile.md</c>.</param>
/// <param name="Topic">What the choice is about.</param>
/// <param name="Choice">What the library does.</param>
/// <param name="Observable">The browser behaviour the choice matches, and where it is documented.</param>
/// <param name="Evidence">How well the choice is backed.</param>
public sealed record ProfileEntry(string Id, string Topic, string Choice, string Observable, ProfileEvidence Evidence);

/// <summary>
/// The choices made where WAI-ARIA, HTML-AAM and Core-AAM leave room, each matching what Chromium exposes. The same
/// list is written out in <c>docs/accessibility-chromium-profile.md</c>.
/// </summary>
public static class ChromiumProfile
{
    /// <summary>
    /// The <c>aria-level</c> of an element with the <c>heading</c> role that has no level: 2. WAI-ARIA 1.2 requires the
    /// property and defines no default; browsers expose 2.
    /// </summary>
    public const int DefaultHeadingLevel = 2;

    /// <summary>The entries, in the order the documentation lists them.</summary>
    public static IReadOnlyList<ProfileEntry> Entries { get; } =
    [
        new("generic-fallback", "HTML elements HTML-AAM does not list", "Exposed with the generic role (font, center, marquee, unknown elements, autonomous custom elements).", "Chrome exposes unlisted elements as generic containers.", ProfileEvidence.Unverified),
        new("empty-alt-image", "img with an empty alt", "The role is none unless aria-label has text or aria-labelledby names an element. A title does not name it.", "wpt html-aam/roles-contextual.html el-img-empty-alt-title and the aria-label and aria-labelledby cases.", ProfileEvidence.TestSuite),
        new("unnamed-landmark-token", "role=region or role=form without a name", "The token is skipped like an unknown token, so the next token or the native role applies.", "wpt wai-aria/role/region-roles.html, form-roles.html, fallback-roles.html; WAI-ARIA 1.2 section 9.1.", ProfileEvidence.TestSuite),
        new("named-native-landmarks", "section, form and sectioned aside", "region and complementary only with an accessible name; otherwise generic. A title attribute counts as a name. (form is always form, see unnamed-form.)", "wpt html-aam/roles-contextual.html el-section-title, el-aside-in-section-title.", ProfileEvidence.TestSuite),
        new("section-header-footer", "header and footer outside the body scope", "Role generic with the internal role sectionheader or sectionfooter, exposed (not ignored), exported under those names. A header or footer whose role is explicit keeps that role.", "Chrome 156 output on the svg probe fixture (header and footer in main, section and article are sectionheader and sectionfooter; the body-level ones are banner and contentinfo) and 96 such elements on 240 corpus pages. The HTML-AAM draft names the roles; the wpt pages that expect them stay known failures because the role API reports generic.", ProfileEvidence.ChromeObserved),
        new("landmark-scope", "What scopes header, footer and aside", "The nearest ancestor among article, aside, nav, section (sectioning), main, body. header and footer are landmarks only with no such ancestor except body; aside is complementary when the nearest is main or body.", "wpt html-aam/roles-contextual.html and aside-in-prefixed-article.html.", ProfileEvidence.TestSuite),
        new("li-accessibility-parent", "li", "listitem when the nearest ancestor with a role other than generic or presentational has the list role (ul, ol, menu, dir, role=list); otherwise generic.", "wpt html-aam/roles-generic.tentative.html el-li-within-generic-within-list-parent, el-li-within-explicit-role-list-parent.", ProfileEvidence.TestSuite),
        new("th-header-kind", "th in the auto scope state", "columnheader inside thead or in a row with no td; rowheader in a row that has a td. scope=col|colgroup gives columnheader, scope=row|rowgroup gives rowheader.", "wpt html-aam/table-roles.html. The auto rule is a simplification of the HTML header-cell algorithm; Chrome 156 agrees on the table fixture, which sets scope on every th.", ProfileEvidence.Unverified),
        new("computed-role-names", "Names of computed roles", "presentation is reported as none, img as image, directory as list.", "wpt wai-aria/role/synonym-roles.html; Core-AAM computed role.", ProfileEvidence.TestSuite),
        new("role-token-matching", "Role tokens", "Split on the HTML ASCII whitespace; matched ASCII case-insensitively; the first valid, non-abstract token wins; image is accepted for img.", "wpt wai-aria/role/fallback-roles.html, invalid-roles.html, roles.html.", ProfileEvidence.TestSuite),
        new("presentational-conflict", "none or presentation on a focusable element or one with a global aria-* attribute", "Ignored: the implicit role applies. Any state or property marked global in WAI-ARIA 1.2 counts, deprecated ones and prohibited ones included. Non-global attributes do not.", "wpt wai-aria/role/role_none_conflict_resolution.html and .tentative.html.", ProfileEvidence.TestSuite),
        new("inherited-presentational", "Required owned elements of a presentational element", "They are presentational too, even with global aria-* attributes; a focusable one is not. An owned element with its own non-presentational role keeps it.", "wpt wai-aria/role/role_none_conflict_resolution_spec_ambiguities.tentative.html.", ProfileEvidence.TestSuite),
        new("children-presentational", "Descendants of roles with presentational children", "Descendants of a button, tab or image role keep their own roles; they are not made presentational (WAI-ARIA 1.2 section 5.2.9 says they are).", "Chrome 156 output on the corpus: svg, heading and span inside a button keep their roles.", ProfileEvidence.ChromeObserved),
        new("static-focusable", "Focusable by markup", "Valid tabindex, links with href, enabled form controls except hidden inputs, iframe, the first summary of a details, audio and video with controls, editing hosts, none of it inside an inert subtree. Style is not consulted.", "HTML 6.6.3 focusable area; iframe, media controls and summary behaviour are unverified.", ProfileEvidence.Unverified),
        new("empty-aria-value", "An empty aria-* value", "Treated as not specified and not reported.", "WAI-ARIA 1.2 section 9.2 for booleans; extended to all types.", ProfileEvidence.Unverified),
        new("heading-default-level", "role=heading without aria-level", "Level 2 (DefaultHeadingLevel).", "Browsers expose level 2; WAI-ARIA 1.2 leaves it undefined.", ProfileEvidence.Unverified),
        new("option-context", "option outside select and datalist", "No role.", "HTML-AAM lists option only in a list of options.", ProfileEvidence.Unverified),
        new("summary-role", "summary", "The first summary child of a details has no role of its own; any other summary is generic.", "wpt html-aam/summary.html.", ProfileEvidence.TestSuite),
        new("foreign-elements", "SVG and MathML elements", "Only the roots are mapped (svg: graphics-document, math: math); other foreign elements have no implicit role until SVG-AAM is applied.", "HTML-AAM defers both to their own mapping documents.", ProfileEvidence.Specification),
        new("switch-input", "input type=checkbox with the switch attribute", "switch.", "wpt html-aam/roles.tentative.html el-input-checkbox-switch.", ProfileEvidence.TestSuite),
        new("select-kind", "select", "listbox when multiple is present or size is above 1; otherwise combobox.", "wpt html-aam/roles.html el-select-listbox; HTML-AAM select entries.", ProfileEvidence.TestSuite),
        new("input-suggestions", "input with a list attribute", "combobox when list names a datalist in the same document, for the text, search, tel, url and email types.", "HTML-AAM el-input-textetc-autocomplete.", ProfileEvidence.Specification),
        new("required-attribute-native", "Required states and properties of an explicit role on a native element", "Supplied by the native element: heading level for h1-h6, checked for checkbox and radio inputs, selected for option, valuenow for range and number inputs, meter and progress, expanded and controls for select and text inputs. Required attributes are checked only for explicit roles that differ from the element's native role.", "ARIA in HTML conformance model and HTML-AAM section 3.6.", ProfileEvidence.Unverified),
        new("value-minimums", "Lower bounds of integer attributes", "aria-level, aria-posinset, aria-colindex, aria-rowindex, aria-colspan at least 1; aria-rowspan at least 0; aria-setsize, aria-colcount, aria-rowcount at least -1.", "WAI-ARIA 1.2 prose of those properties.", ProfileEvidence.Specification),
        new("tree-keeps-ignored", "Ignored nodes in the tree", "The tree keeps nodes that are ignored (hidden by visibility, aria-hidden or inert, presentational, uninteresting) with their reasons, and the children of an ignored node stay its children. Nodes that are not rendered at all have no tree node. Chrome returns no node at all for a visibility: hidden or aria-hidden element and its subtree, and none for a noscript element; those are the nodes only we list (oursOnlyIgnored in the differential), and they are ignored, so the exposed tree is the same.", "Chrome 156 output on the hidden and script fixture pages. The children of a visibility: hidden element that are visible again appear under its nearest exposed ancestor, which is what lifting the children of an ignored node gives.", ProfileEvidence.ChromeObserved),
        new("ignored-reason-names", "Spelling of ignored reasons", "notVisible (visibility), ariaHiddenElement and ariaHiddenSubtree, inertElement and inertSubtree, presentationalRole, uninteresting. An ignored node is exported with the role none. Chrome also uses labelFor (a label whose text is the control name) and notRendered, which we do not produce.", "Names follow what the DevTools Protocol returns for ignoredReasons; uninteresting and presentationalRole observed in Chrome 156 on the fixture pages.", ProfileEvidence.ChromeObserved),
        new("generic-pruning", "Generic elements", "A generic element is exposed (not ignored) whatever it contains or carries, including div, span and an empty container with only element children. The exceptions that are ignored as uninteresting are the html and body elements and the b and i elements (their children belong to the nearest exposed ancestor). An element with no role at all is ignored too, unless it has an internal role (see internal-roles).", "Chrome 156 output on the fixture pages hidden, landmarks, overflow, positioned, whitespace and background: every div and span is generic and exposed, html and body are ignored as uninteresting, b and i have no node. Not observed: an empty div or span, other inline formatting elements (u, s, small and so on) and a template inside a list (ignored there, exposed as generic under body).", ProfileEvidence.ChromeObserved),
        new("static-text-nodes", "Text nodes", "Each text node is a StaticText node with its text, white space collapsed. A white-space-only text node is kept, as an ignored node, only when its parent is inline. Leading and trailing white space is trimmed at the start and end of a block. There are no InlineTextBox children, and no StaticText for the text of a textarea, an option or an SVG title, desc or metadata element (see text-control-leaves). Generated text (::before, ::after, list markers) is not a node (needs rendering).", "Chrome exposes StaticText with InlineTextBox children; the boxes need layout. Names and text of every matched StaticText equal Chrome 156 on the fixture pages, except mathematical alphanumerics (mi text uses text-transform: math-auto).", ProfileEvidence.ChromeObserved),
        new("not-rendered-absent", "Elements that are not rendered", "display: none (including the hidden attribute and template through the user-agent sheet), the contents of a closed details other than its first summary, and the contents of content-visibility: hidden have no tree node. An area inside a map is exposed although the rendering rules give it display: none.", "HTML section 15.3.1, HTML section 4.11.1, CSS Containment 2 section 4.2; the area exception follows browsers that expose image-map areas.", ProfileEvidence.Unverified),
        new("name-hidden-referenced", "Hidden nodes in a name", "A hidden node contributes nothing, except a root of the computation or a node named by aria-labelledby or aria-describedby. Below such a root, a node is left out only when hidden for a reason the root does not have: a hidden root brings its whole subtree in. A node hidden only by visibility still lets its visible descendants through. Native label, caption and legend elements are not directly referenced: hidden ones are skipped.", "wpt accname/name/comp_labelledby_hidden_nodes.html, comp_hidden_not_referenced.html, html-aam/hidden-names.html.", ProfileEvidence.TestSuite),
        new("labelledby-fallthrough", "aria-labelledby that names no text", "When every referenced node gives no text, the computation continues with aria-label and the later steps.", "AccName 1.2 step 2B is silent; wpt accname/name/comp_label.html passes with this reading.", ProfileEvidence.TestSuite),
        new("labelledby-used-once", "A node named by aria-labelledby inside another computation", "A node used as an aria-labelledby or aria-describedby target in a computation is left out when the same computation meets it again as content.", "wpt accname/name/comp_name_from_content.html (heading with two links).", ProfileEvidence.TestSuite),
        new("embedded-controls", "Embedded controls", "A textbox, combobox, listbox, slider, spinbutton, progressbar, meter or scrollbar inside a label, a referenced node or contents being read contributes its value (input value, textarea text, selected options, aria-valuetext or aria-valuenow) and its own aria-label is ignored. The element being named is exempt, so aria-labelledby naming itself still reads its aria-label. A non-native combobox with no selected option is read as contents.", "wpt accname/name/comp_embedded_control.html and manual/name_*_label_embedded_*.", ProfileEvidence.TestSuite),
        new("name-prohibited-roles", "Naming of roles that prohibit it", "aria-labelledby, aria-label and title still name elements whose role prohibits naming (generic, paragraph and so on); such roles never take a name from contents.", "wpt html-aam/accname-computation-by-element/phrasing-elements.html and accname/name/comp_label.html.", ProfileEvidence.TestSuite),
        new("native-name-sources", "Native name sources", "Form controls: label elements, then (buttons) value, then title, then placeholder, then aria-placeholder; input type=image: labels, alt, title, then Submit; submit and reset buttons fall back to Submit and Reset. img and area: alt (an img with alt=\"\" has no name from title or contents); an img with no alt that fills its figure takes the figcaption after title. fieldset: the first rendered legend; table: the first rendered caption; figure: its figcaption; optgroup, option and track: label; svg elements: the first title child. A select is never named from its options.", "wpt html-aam/accname-computation-by-element/*, accname/name/comp_tooltip.html, comp_host_language_label.html.", ProfileEvidence.TestSuite),
        new("generated-content-names", "CSS generated content in names", "::before and ::after content is part of the name of the contents: strings, attr(), counter() and counters() (CSS Lists 3 scopes, including the counter properties of the pseudo-element itself) and quotes (open-quote and close-quote as the curly double quotes). Alternative text after / replaces the content and is set off by a space on each side; a block-level pseudo-element likewise. ::marker boxes are not generated.", "wpt accname/name/comp_name_from_content.html, comp_name_from_content_alt_counter_multi_instance.html; the ::marker pages are tentative and listed as known failures.", ProfileEvidence.TestSuite),
        new("text-transform-in-names", "text-transform in names", "The transform of the parent element (uppercase, lowercase, capitalize) is applied to the text of a text node before it joins a name.", "wpt accname/name/comp_name_from_content.html.", ProfileEvidence.TestSuite),
        new("name-spacing", "Joining in name from contents", "A child whose display is not inline (or contents) is set off by a space on each side; br adds a space; inline children run together; a descendant holding only white space keeps it. The result has white space collapsed and trimmed (ASCII white space only).", "wpt accname/name/comp_name_from_content.html, comp_text_node.html.", ProfileEvidence.TestSuite),
        new("aria-owns-resolution", "aria-owns", "Owners are visited in document order and the first owner of an element wins. An element never owns itself, the root element or an ancestor of the owner in the tree as built so far. aria-owns on an element that is not rendered, aria-hidden or inert, or naming an element that is not rendered or has visibility: hidden, is ignored. Owned elements follow the DOM children of the owner in the order of the attribute. Work is bounded.", "wpt accname/aria-owns.html; WAI-ARIA 1.2 section 6.6.6.", ProfileEvidence.TestSuite),
        new("aria-disabled-inherited", "aria-disabled on ancestors", "An element is disabled when an ancestor has aria-disabled=\"true\", as well as by its own attribute or a disabled fieldset.", "Chrome exposes disabled on descendants of an aria-disabled element.", ProfileEvidence.Unverified),
        new("default-states", "States exposed without an attribute", "A combobox is expanded=false; checkbox, radio, switch and menuitem checkbox and radio roles are checked=false; option and tab are selected=false. Range roles (slider, scrollbar, meter, progressbar) default to 0 and 100 and a slider with no value sits at the midpoint; an input type=range clamps its value into its range. The first summary of a details is expanded=false when closed.", "HTML section 4.10.5.1.13; observed in Chrome 156 on the forms fixture (combobox, checkbox, radio, option, slider, progress, meter, details).", ProfileEvidence.ChromeObserved),
        new("set-position", "posinset and setsize", "Items with the role listitem, menuitem (and its checkbox and radio forms), option, radio, tab, treeitem, or article directly in a feed, form a set with the siblings of that kind under the nearest ancestor that is not generic, none, ignored or (for treeitem and menuitem) a group. A native radio button belongs to the set of its name in its form. Ignored items are not counted; an explicit aria-posinset restarts the count and the first aria-setsize found is used for the set. The tree holds the computed values; the Chrome-shaped export leaves them out unless the author gave them (see export-set-position).", "Core-AAM section 5.4 and HTML-AAM.", ProfileEvidence.Unverified),
        new("focus-order", "Sequential focus order", "Positive tabindex values ascending, then tabindex 0 and natively focusable elements in document order. A negative tabindex is focusable but not in the order. Disabled, inert, not rendered and visibility: hidden elements are not focusable. Radio buttons are not collapsed to one tab stop per group and scrollers are not made focusable.", "HTML section 6.6.3; Chrome differs for radio groups and scrollers.", ProfileEvidence.Unverified),
        new("export-role-names", "Role names in the Chrome-shaped export", "Core-AAM computed role names are used, except the nodes with an internal role (see internal-roles), StaticText for text and RootWebArea for the document.", "Chrome DevTools Protocol AXNode role values; observed on all fixture pages.", ProfileEvidence.ChromeObserved),
        new("unnamed-form", "form without an accessible name", "A form element has the form role whether or not it has a name.", "Chrome 156 exposes the unnamed form of the forms fixture as form (HTML-AAM maps form to form; the landmark rule needs a name, the role does not).", ProfileEvidence.ChromeObserved),
        new("internal-roles", "Roles that are not WAI-ARIA roles", "Elements WAI-ARIA has no role for, and that Chrome exposes, have AxNode.InternalRole and are not ignored: label (LabelText), legend (Legend), br (LineBreak), iframe (Iframe), the first summary of a details (DisclosureTriangle), input type=date (Date) and type=color (ColorWell), which also state their value. The MathML elements math, mi, mo and mn (MathMLMath, MathMLIdentifier, MathMLOperator, MathMLNumber) keep their WAI-ARIA role and are exported under these names; svg is covered by svg-root-role. Other date and time input types, other MathML elements and the SVG graphics elements are not covered.", "Chrome 156 output on the forms, implied and iframe fixture pages (label, iframe, summary, date, colour, svg, math, mi, mo, mn); legend and br are inferred from the same naming.", ProfileEvidence.ChromeObserved),
        new("svg-root-role", "Role of an svg element", "An svg with an implicit role keeps graphics-document and has the internal role image, exported as image. When something inside it is exposed (rendered text, a link, a foreignObject, an element with a role; graphics elements and nested svg elements do not count) the internal role is SvgRoot instead. An svg with no children, or nested in another svg, and no name is ignored (uninteresting). An svg with an explicit role keeps it.", "Chrome 156 output on the svg probe fixture: title, desc, path, g, use, nested, tabindex and aria-label svgs are image and an empty svg has no node; text, foreignObject, a link, a role=group child make SvgRoot, with or without a name; 1,381 image and 3 SvgRoot svg elements on 240 corpus pages.", ProfileEvidence.ChromeObserved),
        new("input-password-file", "input type=password and type=file", "A password field is a textbox whose value is one bullet for each character of its value attribute (the characters are not exposed); a file field is a button whose value is the label No file chosen, whatever its multiple attribute.", "Chrome 156 output on the property probe pages (testdata/rendered/pages/axprops*.html, captures beside them) and the corpus; HTML-AAM lists no role for either.", ProfileEvidence.ChromeObserved),
        new("row-name", "Name of a table row", "A row is not named from its cells; aria-label, aria-labelledby and title still name it. Cells are named from their contents.", "Chrome 156 output on the table fixture (rows have no name, cells do).", ProfileEvidence.ChromeObserved),
        new("text-control-leaves", "Children of textarea, option and SVG title", "A textarea and an option have no child nodes, and neither do the SVG title, desc and metadata elements; the text is the control value, the option label or not rendered. The name computation still reads it.", "Chrome 156 output on the forms and implied fixtures (no StaticText for the textarea text, the option labels or the SVG title).", ProfileEvidence.ChromeObserved),
        new("option-focusable", "Options of a select", "An enabled option inside a select is focusable (focusable=true) but not a stop of the sequential focus order.", "Chrome 156 output on the forms fixture.", ProfileEvidence.ChromeObserved),
        new("list-item-level", "level of a list item", "A listitem has the level property: the number of list ancestors, unless aria-level is given.", "Chrome 156 output on the implied and whitespace fixtures: level=1 for items of a top-level list. Depth greater than 1 is inferred from the property name and unobserved.", ProfileEvidence.ChromeObserved),
        new("select-popup", "haspopup of a select", "A drop-down select (combobox role) has haspopup=menu.", "Chrome 156 output on the forms fixture.", ProfileEvidence.ChromeObserved),
        new("number-input-bounds", "Bounds of input type=number", "A number input without min and max has valuemin=0 and valuemax=0; with them, their values. A native slider or spin button states its value as its value text as well.", "Chrome 156 output on the forms fixture (spinbutton 0, 0 and valuetext 3; slider valuetext 4).", ProfileEvidence.ChromeObserved),
        new("export-native-labelledby", "labelledby in the export for native labels", "In the Chrome-shaped export a node named by a label, caption or legend (not by aria-labelledby) has a labelledby property naming those elements. The tree API reports only aria-labelledby as the LabelledBy relation. SVG title elements are not reported.", "Chrome 156 output on the forms and table fixtures (controls and the captioned table); an svg named by its title has none.", ProfileEvidence.ChromeObserved),
        new("export-set-position", "posinset and setsize in the export", "The export never states posinset or setsize, whether the author gave aria-posinset and aria-setsize or the tree computed them. The tree keeps both.", "Chrome 156 output on the property probe pages (testdata/rendered/pages/axprops*.html, captures beside them) and the corpus: 214 occurrences on 28 corpus pages where only we stated them, and none stated by Chrome in 12,788 captures.", ProfileEvidence.ChromeObserved),
        new("foreign-object", "SVG foreignObject", "The foreignObject element is ignored with the reason presentationalRole.", "Chrome 156 output on the implied fixture.", ProfileEvidence.ChromeObserved),
        new("link-url", "url of links and images", "The url property is the href of a link or area, or the src of an img, resolved against AccessibilityOptions.BaseUrl (and a base element). Without a base URL it is the attribute as written.", "Chrome 156 output on the fixture pages: absolute URLs for links and the image.", ProfileEvidence.ChromeObserved),
        new("layout-facts-scope", "What rendered facts change", "Facts are optional (AccessibilityOptions.Facts). Without them every choice below is off and the tree is what it is without layout. With them, only the choices in the entries layout-generic-pruning, layout-table, list-marker-node, layout-select-popup, layout-white-space and layout-hidden apply. Facts must describe the same document under the same style context, or the build is refused; an update never keeps them (a new snapshot needs new facts, so the update builds afresh and equals Build with those facts).", "Facts are one capture of one page (DOMSnapshot.captureSnapshot), so a changed document or context makes them stale; reusing them would put Chrome's layout of the old page on the new one.", ProfileEvidence.Specification),
        new("layout-generic-pruning", "Which generic containers Chromium leaves out (with facts)", "A generic container (div, span, li, p without a better role, unknown elements, body, b, i) is ignored with the reason uninteresting unless one of these holds: it is a section, header, footer or aside; it has an id, title, tabindex, role or any aria-* attribute; it is positioned; it scrolls (overflow auto or scroll and more content than room); its display is inline-block, inline-flex or another inline-level non-inline value; or it is a block, flow-root or list-item box whose own children are inline content (laid-out text, inline boxes, floats or out-of-flow boxes) with no in-flow block-level child. A display: inline box (an a with no href is one) and a span whose display is not inline-level, and flex, grid and table containers, are ignored unless an attribute keeps them; a span that is inline-block or inline-flex stays. A ::before or ::after block-level box is a block-level child, an inline one with text is inline content (profile entry generated-content-node); an inline box that has a ::before or ::after box is not left out. A p is ignored the same way when it has no inline content. A plain inline box that is ignored has no node at all (its children belong to the nearest ancestor with a node); a block one stays as an ignored node.", "Chrome 156 output on 634 corpus pages (two samples, one used to find the rule and one held out) and the layout fixture, where the exposed structure equals Chrome's. Over the paired nodes the ignored flag differs for 0.9% of them on each sample, against 12% to 15% without facts. On 240 pages, of 15,681 blocks without id or attributes whose children were all blocks Chrome ignored 15,667, and of 2,947 holding only text or inline boxes it ignored none; of 12,589 static spans without attributes it ignored 12,542. Not explained: blocks whose only children are floats (48 exposed, 22 ignored), a handful of positioned boxes, generics inside video elements, and a share of the paragraphs that Chrome ignores.", ProfileEvidence.ChromeObserved),
        new("layout-table", "Layout tables (with facts)", "An HTML table is a data table (role table, its rows and cells row and cell) when it has a summary attribute, any aria-* attribute, a caption or a cell with scope; or, when it has more than one cell (td or th), a th, a thead, or a visible border on the table or on its first cell; or, whatever else it has, 20 or more rows (tr). Cells, captions, headers and rows of a table nested inside it belong to the nested table. Any other table is a layout table: its internal role is LayoutTable, its rows LayoutTableRow, its cells (td and th) LayoutTableCell; the Core-AAM role stays table, row and cell. The evidence scan is bounded (20,000 elements). A generic element laid out as display: table, table-row or table-cell has the same internal roles.", "Chrome 156 output on 171 tables of 240 corpus pages (162 judged as Chrome did: 6 layout tables looked like data tables, 3 data tables like layout tables) and the layout and table fixtures. A table with one cell is a layout table even with borders or a th (the table fixture; 12 of 12 one-cell tables with a th and no aria, summary or scope attribute on 6,000 corpus pages), while a caption makes even a one-cell table a data table (3 of 3). Among 1,604 tables with none of this evidence and no nested table, 35 of the 88 that Chrome called data tables had 20 or more rows and no table with that many rows was a layout table (at 16 rows: 9 layout tables); the other 53 data tables are small ones whose cause is not known (a background colour on the first cell is 8 times as common among them). The large layout tables that had header cells were holding nested tables whose header cells they had counted, which is why nested tables are not scanned.", ProfileEvidence.ChromeObserved),
        new("list-marker-node", "List markers (with facts)", "An element whose layout has a ::marker box with text (a list item with a visible marker, not summary, not hidden or visibility: hidden) gets a ListMarker node as its first child, named by the marker text (\"• \", \"1. \"), with one ignored child (none, presentationalRole). The node has no DOM node of its own: its kind is Generated and the export gives it no backendDOMNodeId.", "Chrome 156 output on 634 corpus pages and the whitespace, layout and implied fixtures: the node is named by the marker text and has one ignored child. An item whose role is not listitem (a list item made presentational) has the marker as plain static text instead. A marker is also absent when the item is hidden.", ProfileEvidence.ChromeObserved),
        new("layout-select-popup", "Drop-down select popup (with facts)", "A select with the combobox role that has a box has one MenuListPopup child (a Generated node), and its options and option groups are children of that node. Options are focusable as before.", "Chrome 156 output on 27 corpus pages (3,400 options) and the layout fixture. Not reproduced: the extra ignored node Chrome puts between the popup and the options of a select that has an option group (forms fixture, 3 nodes).", ProfileEvidence.ChromeObserved),
        new("layout-white-space", "Static text of white space (with facts)", "A text node of white space only has a static text when it was drawn (it has a text box) between two elements that are display: inline; any other white space has none. Text with characters is unchanged. Such a static text is not ignored.", "Chrome 156 output on 240 corpus pages: of 2,099 drawn spaces between two display: inline elements Chrome has a static text for 1,485; of 1,377 drawn elsewhere it has one for 33; of 24,339 collapsed spaces (no text box) it has one for 34. The 614 spaces between inline elements that have none are not explained by position, line, parent role or display.", ProfileEvidence.ChromeObserved),
        new("layout-hidden", "Hiding that depends on layout (with facts)", "An HTML element whose style renders it but whose capture has no box is hidden as not rendered, except display: contents, option, optgroup, area, map, slot, html and body; SVG and MathML elements are never hidden this way. Zero size, clipping and an off-screen position do not hide anything: Chrome keeps such nodes in the tree. Chrome reports no bounding box, off-screen state or scrollable state in Accessibility.getFullAXTree, so the export has none.", "Chrome 156 output on the overflow and positioned fixtures (clipped, rect-clipped and off-screen elements are exposed) and the corpus: of about 220,000 nodes with a box on 240 pages, 2 are notRendered; none of 121,682 nodes of 120 pages has a bounding-box, off-screen or scrollable property.", ProfileEvidence.ChromeObserved),
        new("text-transform-static-text", "text-transform on static text", "The text of a static-text node is the rendered text: text-transform (uppercase, lowercase, capitalize) applies, as it does in names.", "Chrome 156 output on the corpus: StaticText of an uppercased link is upper case.", ProfileEvidence.ChromeObserved),
        new("generic-title", "title on a generic element", "A generic element with a title has the title as its description, not as its name: WAI-ARIA 1.2 lists generic as Name From: prohibited. Elements with other roles keep naming from title. The nine WPT html-aam cases that expect a name from title on b, bdi, bdo, i, q, samp, small, u and application are known failures; application is not an HTML element, so it is an unknown element with the generic role.", "Chrome 156 output on the corpus: generic nodes with a title have no name and the title as description. HTML-AAM maps these elements to generic and its tooltip rule would name them; Chromium does not.", ProfileEvidence.ChromeObserved),
        new("description-repeats-name", "title that repeats the name", "A title is not also the description when the name is made from text alone and equals the title.", "Chrome 156 output on the corpus: no description on links whose text equals their title.", ProfileEvidence.ChromeObserved),
        new("description-list-role", "dl element", "A dl has the role DescriptionList (an internal role), not list; its items do not count as list levels.", "Chrome 156 output on the corpus.", ProfileEvidence.ChromeObserved),
        new("figcaption-role", "figcaption element", "A figcaption has the internal role Figcaption, not caption.", "Chrome 156 output on the corpus.", ProfileEvidence.ChromeObserved),
        new("orphan-list-item", "li outside a list", "An li whose parent is not a list is still a listitem.", "Chrome 156 output on the corpus.", ProfileEvidence.ChromeObserved),
        new("aside-in-sectioning", "aside nested in sectioning content", "An aside with no name inside article, aside, nav, section or a complementary role is generic, not a complementary landmark.", "Chrome 156 output on the corpus.", ProfileEvidence.ChromeObserved),
        new("presentational-table", "table with role none or presentation", "Cells inside are generic; rows and row groups are ignored as uninteresting. WAI-ARIA 5.2.7 would make all of them presentational.", "Chrome 156 output on the corpus.", ProfileEvidence.ChromeObserved),
        new("noscript-not-rendered", "noscript", "noscript is not rendered (display: none), as HTML section 15.3.1 says when scripting is enabled.", "Chrome 156 lists noscript elements in body as ignored with the reason notRendered (corpus page 00c499). Hiding it adds 1,611 Chrome-only nodes and 235 name mismatches to the sample compared with leaving it visible; the cause is not traced.", ProfileEvidence.ChromeObserved),
        new("live-region-properties", "live region properties", "live, atomic and relevant are exposed only on live regions. An alert, log or status is live by its role; relevant defaults to additions text; atomic defaults to the role's value, else false.", "Chrome 156 output on the corpus: no live, atomic or relevant on other nodes; WAI-ARIA 1.2 defaults.", ProfileEvidence.ChromeObserved),
        new("accesskey-shortcut", "accesskey", "An element with an accesskey has keyshortcuts Alt+ followed by the attribute exactly as written: an empty value gives Alt+, a list such as a b or a multi-character key is kept whole. aria-keyshortcuts wins when both are given.", "Chrome 156 output on the property probe pages (testdata/rendered/pages/axprops*.html, captures beside them) and the corpus (Linux).", ProfileEvidence.ChromeObserved),
        new("autocomplete-popup", "hasPopup", "hasPopup is menu for aria-haspopup true and the token for menu, listbox, tree, grid or dialog on any element, a summary or a div included. A missing, false or unknown value (1, bogus) states none. Every combobox that names none has listbox (a drop-down select has menu, see select-popup), and aria-haspopup false does not remove it. A text field with aria-autocomplete adds no popup unless it is a combobox.", "Chrome 156 output on the property probe pages (testdata/rendered/pages/axprops*.html, captures beside them) and the corpus.", ProfileEvidence.ChromeObserved),
        new("option-selectedness", "selected state of options", "An option is selected by its selectedness (HTML 4.10.7), including the first enabled option of a single-choice select that has none selected; aria-selected on the option overrides. A disabled native option states no selected. The value of the select is the text of that option, with the select text-transform applied.", "Chrome 156 output on the property probe pages (testdata/rendered/pages/axprops*.html, captures beside them) and the corpus.", ProfileEvidence.ChromeObserved),
        new("constraint-invalid", "invalid from form constraints", "invalid is true when a control that is not disabled and has no readonly attribute fails one of: a required checkbox that is unchecked; a required radio group (same name in the same form) with no checked button; a required file field; a required date, time, month, week or datetime-local field with no valid value; a required list box or multiple select with nothing selected; a required drop-down whose chosen option is the empty-valued first option (also when it is marked selected and disabled); a number below min, above max or off the step grid counted from min; a date or month outside min and max; an email or url value that does not parse; a pattern that does not match the whole value of a text, search, tel, url, email or password field. Text fields, number fields and text areas are not reported when required and empty. An explicit aria-invalid=false replaces the report. Kept internal; the public invalid state follows ARIA. Step mismatch with no min is never reported because the step base is then the value itself.", "Chrome 156 output on the property probe pages (testdata/rendered/pages/axprops*.html, captures beside them) and the corpus.", ProfileEvidence.ChromeObserved),
        new("required-exposure", "required", "The export states required for roles that take it, and not for searchbox, native select, checkbox, radio, date and button.", "Chrome 156 output on the corpus.", ProfileEvidence.ChromeObserved),
        new("url-roles", "url property", "Only a link and an image state a URL; an anchor an author gave another role does not.", "Chrome 156 output on the corpus.", ProfileEvidence.ChromeObserved),
        new("url-serialization", "url serialization", "URLs are resolved and serialized as the URL Standard does: host lower-cased, default port dropped, dot segments removed, percent-escape case kept, and an empty path serialized as /.", "Chrome 156 output on the corpus.", ProfileEvidence.ChromeObserved),
        new("expanded-list-item", "expanded on a list item", "aria-expanded is exposed on a list item although WAI-ARIA 1.2 does not allow it there.", "Chrome 156 output on the corpus.", ProfileEvidence.ChromeObserved),
        new("relation-targets", "relation targets in the export", "controls, details, errormessage, flowto and activedescendant list only targets that are exposed; labelledby, describedby and owns list every referenced element. A target that is not rendered is still a node in Chromium when it computes a name.", "Chrome 156 output on the corpus.", ProfileEvidence.ChromeObserved),
        new("ignored-reasons", "ignored reasons", "The export gives one reason, the first that applies in the order notRendered, ariaHiddenElement, ariaHiddenSubtree, inertElement, inertSubtree, notVisible, emptyAlt, labelFor, presentationalRole, uninteresting. An img with an empty alt is emptyAlt. An element with aria-hidden=true of its own is ariaHiddenElement even inside another aria-hidden element; its descendants are ariaHiddenSubtree (Chrome 156 output on 400 corpus captures: 104 of 2,901 own-aria-hidden nodes were nested, and every one was the element).", "Chrome 156 output on the corpus.", ProfileEvidence.ChromeObserved),
        new("positioned-blockification", "display of positioned and floated elements, flex and grid items, and contents elements", "An absolutely or fixed positioned or floated element has its display blockified (CSS Display 3 section 2.7) before names add spaces around inline-level text, and so does a child of a flex or grid container (CSS Display 3 section 2.7 blockifies flex and grid items too). A display: contents element counts as a block for the spaces. Spaces are added on each side of such a child; plain inline children run together.", "Chrome 156 output on the corpus (hidden-text spans in links) and on a generated probe page of 150 links (10 parent displays by 15 child displays) and 20 flex, grid and inline-flex links mixing text and spans: all agree with this rule (testdata/rendered/pages/nameprobe.html); CSS Display 3 section 2.7.", ProfileEvidence.ChromeObserved),
        new("list-item-in-widget", "li inside a list with another role", "An li with no role of its own whose ul, ol or menu parent has an explicit role other than list, none, presentation or generic (menu, menubar, tablist) is ignored as presentational. An li whose parent is not a list element stays a listitem.", "Chrome 156 output on 500 corpus captures: 273 such li ignored as presentationalRole (parents menu, menubar, tablist), none exposed as listitem; 40,000 li in plain lists are listitems.", ProfileEvidence.ChromeObserved),
        new("label-for", "text-only label of a checkbox or radio", "A label that holds only text, and the checkbox or radio button it labels when it wraps it, and labels a checkbox or a radio button, whether it wraps the control or names it with for, before or after it, is ignored with the reason labelFor, and its text nodes are ignored as presentational. A label with an element child, or a label of any other control, stays a LabelText.", "Chrome 156 output on 300 corpus captures: all 65 text-only labels of checkboxes and radios are ignored as labelFor, all 66 labels with element children are LabelText, and text labels of text fields, selects and textareas are LabelText.", ProfileEvidence.ChromeObserved),
        new("wbr-not-rendered", "wbr", "A wbr element is ignored with the reason notRendered.", "Chrome 156 output on the corpus: every wbr in 600 captures (5,021 nodes).", ProfileEvidence.ChromeObserved),
        new("generated-content-node", "::before and ::after boxes", "With rendered facts, each ::before and ::after box that was laid out is a node under its element (first, after a list marker; last), holding the static text of its generated text when it has some. A box whose display is inline (or contents) is ignored with the reason uninteresting. Any other display is a generic node. An empty block-level box is a node only inside an inline-level host (a link, an inline-block); an empty inline-block box is always one; an empty block box in a block host has none. A container with no children but generated inline text is kept like one with text (it has inline content), and an inline element with a box of generated content is a node (ignored) rather than left out. Not matched: pseudo boxes whose display is table, flex, grid, table-cell or list-item (Chromium nests them differently).", "Chrome 156 output on two generated probe pages (testdata/rendered/pages/pseudoprobe.html and pseudoprobe2.html: inline, block, inline-block, empty, sized, absolute and floated boxes in links, divs, buttons, headings and list items) and 2,095 corpus captures, where chromeOnly nodes fell from 1.98% to 0.9%.", ProfileEvidence.ChromeObserved),
        new("control-text-node", "what a form control draws inside itself", "With rendered facts, a text field (an input exposed as textbox, searchbox or spinbutton, and a textarea) has a generic child with the editable state holding a static text of the value (a password shows bullets; text with a line break is left out); a search or number field, and a text field showing a placeholder, add an ignored node with no reason (the placeholder is a leaf before the editor, for a search or number field the editor sits inside it). An input of type submit, button or reset has a static text of its value, or Submit or Reset. Not matched: date and time inputs (several spinbuttons and a picker button), type image, select and range.", "Chrome 156 output on a generated probe page (testdata/rendered/pages/controlprobe.html) and the corpus.", ProfileEvidence.ChromeObserved),
        new("svg-unrendered-elements", "style and script inside svg", "The text of an SVG style or script element is never part of a name from contents: the elements are not rendered (SVG 2, rendering model).", "Chrome 156 output: 176 links on 26 corpus pages whose svg held a style element; SVG 2 section Rendering order and elements that are never rendered.", ProfileEvidence.ChromeObserved),
        new("name-from-contents-roles", "roles named from contents", "A dt (role term) is named from its contents although WAI-ARIA 1.2 allows only an author name for term; a dfn is not (WPT html-aam phrasing-elements expects that). A time element is not named from its contents.", "Chrome 156 output: 929 dt on 98 corpus pages have their text as the name, 114 time elements on 13 pages have none; WPT html-aam/accname-computation-by-element/phrasing-elements.html for dfn.", ProfileEvidence.ChromeObserved),
        new("disabled-inheritance", "disabled on descendants", "A disabled element passes the state to the descendants that can take focus (a link, a control, an element with a tabindex), not to the others: not to a paragraph, a span, a generic, or a role=button without a tabindex. The ancestor is one with aria-disabled=true or a disabled button or select; a disabled fieldset or optgroup passes nothing on and states nothing itself. An explicit aria-disabled=false ends the inheritance. An option of a disabled select or optgroup is disabled whether or not it can take focus (and stays focusable, see option-focusable).", "Chrome 156 output on the property probe pages (testdata/rendered/pages/axprops*.html, captures beside them) and the corpus.", ProfileEvidence.ChromeObserved),
        new("selected-states", "selected on items that say nothing", "An option, tab or treeitem with no aria-selected states selected=false, unless an item in the same list box, tab list, tree or tree grid carries an aria-selected attribute (any value), when it states nothing. An item outside such a container stands alone. A row, a button or a link states selected only when asked; a row with aria-selected=false states nothing.", "Chrome 156 output on the property probe pages (testdata/rendered/pages/axprops*.html, captures beside them) and the corpus.", ProfileEvidence.ChromeObserved),
        new("option-needs-listbox", "role=option outside a listbox", "An explicit role option is dropped when the first ancestor that is not generic, group or presentational is not a listbox or combobox (and no aria-owns gives the element to one): a button, link or list item keeps its own role, a div is generic. A list between the option and the listbox (an ul inside it) counts.", "Chrome 156 output on the property probe pages (testdata/rendered/pages/axprops*.html, captures beside them) and the corpus: 478 buttons, 31 links and 6 list items on 7 corpus pages that Chrome exposes as button, link and listitem.", ProfileEvidence.ChromeObserved),
        new("readonly-exposure", "readonly", "The export states readonly on text boxes and on grids, tree grids and their cells, and nowhere else: not on a spin button, combobox, checkbox, radio, search box, slider or list box, whatever the markup says. A disabled control states none, and an input of a type other than text, tel, url, email or password with the role textbox states none.", "Chrome 156 output on the property probe pages (testdata/rendered/pages/axprops*.html, captures beside them) and the corpus.", ProfileEvidence.ChromeObserved),
        new("autocomplete-text-fields", "autocomplete", "autocomplete is stated for input and textarea elements only (from aria-autocomplete), and as list for an input with a list attribute that is a combobox, disabled or not. An author aria-autocomplete on a button or a div is not stated.", "Chrome 156 output on the property probe pages (testdata/rendered/pages/axprops*.html, captures beside them) and the corpus.", ProfileEvidence.ChromeObserved),
        new("roledescription-roles", "aria-roledescription", "Not stated on a generic or presentational element; stated on any other role. Chrome hands the text over as UTF-8 bytes read as Latin-1, so a non-ASCII description arrives with each byte as one character (cafe with an acute e becomes the two characters C3 A9); the export does the same.", "Chrome 156 output on the property probe pages (testdata/rendered/pages/axprops*.html, captures beside them) and the corpus: 22 occurrences; \"KunngjÃ¸ring\".", ProfileEvidence.ChromeObserved),
        new("editable-inherited", "editable on the content of an editing host", "An element inside contenteditable (true or empty, or plaintext-only) states editable richtext or plaintext, down to a contenteditable=false element and its content. A static text node inherits its parent state. The editing host inside a disabled or read-only text field keeps its generic node but states no editable.", "Chrome 156 output on the property probe pages (testdata/rendered/pages/axprops*.html, captures beside them) and the corpus.", ProfileEvidence.ChromeObserved),
        new("range-values", "value, valuemin, valuemax and valuetext of ranges", "An author aria-valuenow, aria-valuemin or aria-valuemax wins over the native attribute of an input. A spin button gives no bounds and no value: 0, 0 and 0; a focusable separator is a slider with 0 to 100; a progress bar whose aria-valuenow is not a number rests at 0. Bounds are stated as single-precision numbers (5.56 is 5.559999942779541). The export never states aria-valuetext: valuetext is the value attribute of an input slider or spin button as written (1.00, $675,000), or the number a native slider rests at, and nothing for a progress bar, meter or div.", "Chrome 156 output on the property probe pages (testdata/rendered/pages/axprops*.html, captures beside them) and the corpus.", ProfileEvidence.ChromeObserved),
        new("text-values", "value of text-like controls", "A custom text box, search box or combobox (a div, or a button with the role) states its text, white space collapsed; a text input loses its line breaks; a date input with an invalid value has none; a color input is lower case; a list box states no value. An editing host without block children states its text; one with blocks would need line breaks worked out, which is left out.", "Chrome 156 output on the property probe pages (testdata/rendered/pages/axprops*.html, captures beside them) and the corpus.", ProfileEvidence.ChromeObserved),
        new("placeholder-leaf", "placeholder before the inner editor", "A text, tel, url, email or password field with a placeholder and no value has an ignored leaf before the generic that holds the editor; a search or number field has it before the ignored node that holds the editor, a combobox input the same.", "Chrome 156 output on the property probe pages (testdata/rendered/pages/axprops*.html, captures beside them) and the corpus (axprops3).", ProfileEvidence.ChromeObserved),
        new("combobox-expanded", "expanded on a combobox", "Only a drop-down select states expanded=false; an ARIA combobox states it when its author does.", "Chrome 156 output on the property probe pages (testdata/rendered/pages/axprops*.html, captures beside them) and the corpus.", ProfileEvidence.ChromeObserved),
        new("invalid-spelling", "aria-invalid=spelling", "The export states true.", "Chrome 156 output on the property probe pages (testdata/rendered/pages/axprops*.html, captures beside them) and the corpus.", ProfileEvidence.ChromeObserved),
        new("treeitem-level", "level of a tree item", "A tree item is at level 1 plus the number of groups it sits in, when aria-level is absent.", "Chrome 156 output on the property probe pages (testdata/rendered/pages/axprops*.html, captures beside them) and the corpus.", ProfileEvidence.ChromeObserved),
    ];
}
